  /// Word in the given language, or null for English / anything missing.
  static String? local(String key, String languageId) {
    if (languageId == 'en') return null;
    final index = keys.indexOf(key);
    final list = words[languageId];
    if (index < 0 || list == null || index >= list.length) return null;
    return list[index];
  }
